/* ==UserStyle==
@name          Clean YouTube
@author        0ko (https://userstyles.world/~0ko)
@description   Simplificator and debloater for YouTube aimed at minimizing breaking. Formerly known as Enhancements for YouTube.
@version       3.3.0
@license       MIT
@preprocessor  stylus

@namespace     0ko userstyles
@homepageURL   https://codeberg.org/0ko/UserStyles#clean-youtube
@supportURL    https://codeberg.org/0ko/UserStyles/issues

@var checkbox  noShorts               "No short videos"               1
@var checkbox  noVoiceSearch          "No voice search"               1
@var checkbox  noUpload               "No upload button"              0
@var checkbox  lessCrazyAnimations    "Less crazy button animations"  1
@var checkbox  noMemberships          "No channel memberships"        1

@var select    noHome_                "Home:"                 {" ":"_"}
@var checkbox  noHomeTags             "  No top tags"                 0
@var checkbox  noHomeDifferent        "  No New to you"               1
@var checkbox  noHomeLatestPosts      "  No Latest posts"             0
@var checkbox  noHomeVideoSurveys     "  No video Surveys"            1
@var checkbox  noHomeJunkSections     "  No other junk sections"      1

@var select    noVideo_               "Video:"                {" ":"_"}
@var checkbox  noVideoCornerLogo      "  No logo in corner"           1
@var checkbox  noVideoPlayNext        "  No Next video button"        1
@var checkbox  noVideoClipButton      "  No Clip button"              1
@var checkbox  noVideoWatchNext       "  No Watch next column (emptiness) OR new bottom grid" 0
@var checkbox  noVideoEndscreenVideos "  No endscreen video suggestions" 0
@var checkbox  noVideoSuggestionsTags "  No tags for Watch next"      1
@var checkbox  noVideoVignette        "  No bottom vignette"          0
@var checkbox  noVideoVignetteTop     "  No top vignette (fullscreen)" 0
@var checkbox  noVideoChannelLinks    "  No channel links (socials) in description" 1

@var select    noLogo_                "Logo:"                 {" ":"_"}
@var checkbox  noLogoAccent           "  Monochrome button"           0
@var checkbox  noLogoCountryCode      "  No country code"             1

@var select    noSidebar_             "Sidebar:"              {" ":"_"}
@var checkbox  noSidebarNewnessDots   "  No newness dots"             1
@var checkbox  noSidebarBloat         "  No bloat"                    1

@var checkbox  noSubsTopGap           "Subscriptions: reduce top gap" 1

@var checkbox  noSearchUnrelated      "Search: no unrelated videos"   1

@var checkbox  noCommentsPaidBg       "Comments: no paid background"  1

==/UserStyle== */

imp = !important

@-moz-document domain("youtube.com")

	if noShorts
		/* on Main and in Subscriptions (alt: &:has(a[href^="/feed/subscriptions/shorts"])) */
		ytd-rich-shelf-renderer[is-shorts]
			display: none imp

		/* in Search */
		ytd-reel-shelf-renderer /* section */
			&:has(ytm-shorts-lockup-view-model-v2)
				display: none imp
		ytd-video-renderer /* video */
			&:has(a#video-title[href^="/shorts/"])
				display: none imp

		/* "Shorts remixing this video" */
		#description ytd-reel-shelf-renderer.ytd-structured-description-content-renderer:has(#dismissible)
			display: none imp

	if noVoiceSearch
		#voice-search-button.ytd-masthead
			display: none imp

	if noUpload
		ytd-topbar-menu-button-renderer.ytd-masthead:nth-child(1):has(path[d*="3v3H9v"])
			display: none imp

	if lessCrazyAnimations
		ytd-segmented-like-dislike-button-renderer
		segmented-like-dislike-button-view-model
			.smartimation__border-gradient
				display: none
			.smartimation--active-border .smartimation__background
				opacity: 0
			ytd-lottie-player
				filter: saturate(0)

		#subscribe-button
			.animated-action__background-container
			.animated-action__lottie
			.smartimation__border
				display: none
			ytd-subscribe-button-renderer[animated-action-enabled][subscribed]
				transition: width .1s ease

		/* Remove seekbar gradient */
		.ytp-play-progress
			background: rgb(255, 0, 51) imp

	if noMemberships
		ytd-item-section-renderer
			ytd-recognition-shelf-renderer
				display: none

	/* Homepage */

	if noHomeTags
		ytd-feed-filter-chip-bar-renderer
			display: none imp
		ytd-rich-grid-renderer #contents.ytd-rich-grid-renderer
			padding-top: 16px imp


	if noHomeDifferent
		.ytd-feed-nudge-renderer /* "Looking for something different?" */
		yt-chip-cloud-chip-renderer[chip-style="STYLE_REFRESH_TO_NOVEL_CHIP"]
			display: none imp

	if noHomeLatestPosts
		#dismissible
		.ytd-rich-shelf-renderer
		.ytd-rich-section-renderer
			&:has(ytd-post-renderer)
				display: none imp

	if noHomeVideoSurveys
		#dismissible .ytd-inline-survey-renderer
		ytd-popup-container ytd-checkbox-survey-renderer
			display: none imp

	if noHomeJunkSections
		.ytd-rich-shelf-renderer:has(a[href="/playables"])
		.ytd-rich-shelf-renderer:has(a[href="/feed/storefront"]) /* "Primetime movies for you" */
			display: none imp


	/* Video */

	if noVideoCornerLogo
		.iv-branding
		/*branding-img-container ytp-button*/
		/*branding-img iv-click-target     */
		/*branding-context-container-outer */
			display: none imp

	if noVideoPlayNext
		#ytd-player .ytp-next-button
			display: none imp

	if noVideoClipButton
		yt-button-view-model:has(path[d*="1-1 1 .45 1 1zm-1 9c-.55 0-1 .45-1 1s.45 1 1 1 1-.45 1-1-.45-1-1-1zm3.79-7.77L21"])
			display: none imp

	if noVideoWatchNext
		ytd-watch-next-secondary-results-renderer
		ytd-watch-grid.ytd-page-manager #bottom-grid
			display: none imp

	if noVideoEndscreenVideos
		.ytp-endscreen-content
			display: none imp

	if noVideoSuggestionsTags
		ytd-watch-next-secondary-results-renderer
			yt-related-chip-cloud-renderer.&
				display: none imp
			ytd-watch-flexy[default-layout] & ytd-compact-video-renderer:first-child
				margin-top: 0 imp

	if noVideoVignette
		.ytp-gradient-bottom
			display: none imp

	if noVideoVignetteTop
		.ytp-gradient-top
			display: none imp

	if noVideoChannelLinks
		ytd-video-description-infocards-section-renderer yt-button-view-model
			/* Patreon, Instagram, Twitter, Discord, Reddit */
			&:has(a[href^="https://"])
				display: none imp


	/* Logo */

	if noLogoAccent
		#logo svg g:first-child:not(g g)
				filter: grayscale(100%) contrast(1.25)
		[dark] #logo svg g:first-child:not(g g)
				filter: grayscale(100%) invert(100%) brightness(1.33)

	if noLogoCountryCode
		/* Kind of pointless country code, since the content you see and watch doesn't necessarily depend on it. Imagine every website you visit having a country code in it's logo. */
		#logo
		ytd-topbar-logo-renderer
			#country-code
				display: none


	/* Sidebar */

	if noSidebarNewnessDots
		#newness-dot
			display: none imp

	if noSidebarBloat
		.tp-yt-app-drawer
			/* 1st block */
			a#endpoint[title="Shorts"]
			/* 2nd block */
			a[href^="/feed/clips"][title]
			/* Explore */
			a[href^="/feed/trending"][title]
			a[href^="/channel/UC-9-kyTW8ZkZNDHQJ6FgpwQ"][title]
			a[href^="/feed/storefront"][title]
			a[href^="/channel/UC4R8DWoMoI7CAwX8_LjQHig"][title]
			a[href^="/gaming"][title]
			a[href^="/channel/UCEgdi0XIXXZ-qJOFPf4JSKw"][title]
			/* More from YouTube */
			a[href^="https://studio.youtube.com"][title="Creator Studio"]
			a[href^="https://studio.youtube.com"][title="YouTube Studio"]
			a[href^="https://music.youtube.com"][title="YouTube Music"]
			a[href^="https://www.youtubekids.com"][title="YouTube Kids"]
			a[href^="https://tv.youtube.com"][title="YouTube TV"]
			/* Last block */
			a#endpoint[title="Send feedback"]
			/* Footer */
			#guide-links-secondary.ytd-guide-renderer > a[href="/new"] /* "Test new features" - premium only */
			#footer.ytd-guide-renderer #copyright
				display: none imp

			#sections
				ytd-guide-section-renderer:nth-last-child(2)
				ytd-guide-section-renderer:nth-last-child(3)
					display: none


		/* Subscriptions */

		if noSubsTopGap
			ytd-browse[page-subtype="subscriptions"] .grid-subheader.ytd-shelf-renderer
				margin-top: 0 imp


		/* Search */

		if noSearchUnrelated
			.ytd-search ytd-shelf-renderer
				display: none imp


		/* Comments */

		if noCommentsPaidBg
			#paid-comment-background
				display: none imp

/* ==UserStyle==
@name           Youtube White Progress Bar 
@namespace      github.com/openstyles/stylus
@version        1.0.1
@description    A new userstyle
@author         Me
==/UserStyle== */

@-moz-document domain("youtube.com") {

    :root {
      --first-color: #eee;
      --second-color: #1e1e1e;

    }

    /* Code takken from https://userstyles.org/styles/95280 */
  /* scrubber button */
  .html5-scrubber-button:hover,
  .ytp-chrome-controls .ytp-button[aria-pressed]::after,
  .ytp-scrubber-button:hover,
  .html5-video-player:not(.ytp-color-party) .ytp-swatch-background-color,
  .ytp-swatch-background-color-secondary {
    background: var(--first-color) !important;
  }
  /* progress bar */
  .html5-video-player:not(.ytp-color-party) .html5-play-progress,
  .html5-video-player:not(.ytp-color-party) .ytp-play-progress {
    background: var(--first-color) !important;
  }
  .ytp-volume-slider-track,
  .ytp-volume-slider-handle:before {

    z-index: -117;
  }
  .ytp-settings-button.ytp-hd-quality-badge::after,
  .ytp-settings-button.ytp-4k-quality-badge::after,
  .ytp-settings-button.ytp-5k-quality-badge::after,
  .ytp-settings-button.ytp-8k-quality-badge::after,
  .ytp-settings-button.ytp-3d-badge::after {
    background-color: var(--second-color) !important;
  }
  .ytp-swatch-color-white {
  color: var(--first-color) !important;
}
  .ytp-swatch-color {
    color: var(--first-color) !important;
  }
  .ytp-menuitem[aria-checked="true"] .ytp-menuitem-toggle-checkbox {
    background-color: var(--first-color) !important;
  }
  .ytp-chrome-controls .ytp-button.ytp-youtube-button:hover:not([aria-disabled="true"]):not([disabled]) .ytp-svg-fill-logo-tube-lozenge {
    fill: var(--first-color) !important;
  }
  .ytp-cued-thumbnail-overlay:hover .ytp-large-play-button-bg,
  .ytp-large-play-button.ytp-touch-device .ytp-large-play-button-bg {
    fill: var(--first-color) !important;
  }
  .ytp-large-play-button.ytp-button.ytp-red2:hover,
  .ytp-cued-thumbnail-overlay:hover .ytp-large-play-button.ytp-button.ytp-red2 {
    /*background-image: url(https://github.com/RaitaroH/YouTube-DeepDark/raw/master/YT_Images/large_play_button_hover_ringo-vfl7vEehF.png) !important;*/
    background-image: url(https://s.ytimg.com/yts/img/large_play_button_ringo-vfljWXIdx.png) !important;
    filter: invert(100%) brightness(300%);
  }
  .resume-playback-progress-bar {
    background: var(--first-color) !important;
  }

   .ytp-live-badge[disabled]::before {
	background: var(--first-color) !important;
   }

    /*Mobile YT*/
    .progress-bar-played {
	background-color: var(--first-color) !important;
	}

	.progress-bar-playhead-dot {
	background-color: var(--first-color) !important;
		}	





}

/* ==UserStyle==
@name           `Repositories Grid For GitHub
@author         sapondanaisriwan <sapondanaisriwan@gmail.com> (https://github.com/sapondanaisriwan)
@description    If you want to submit a bug or request a feature please report via github issue. Since I receive so many emails, I can't reply to them all.
@namespace      https://userstyles.world/user/sapondanaisriwan
@homepageURL    https://github.com/sapondanaisriwan/Repositories-Grid-For-GitHub
@supportURL     https://github.com/sapondanaisriwan/Repositories-Grid-For-GitHub/issues
@version        1.0.2
@license        MIT
@preprocessor   stylus

@var select starNewDesign         "⭐ Star New Design" ["Enabled", "Disabled"]
@var checkbox hideStarText        "  💬 Hide Text" 1
@var checkbox dropDownMenu        "  ⬇️ Hide Drop Down Menu" 0

@var select resTap                "📚 Respasatories Tap" ["Enabled", "Disabled"]
@var checkbox fullDescription     "  💬 Full Description" 0
@var checkbox resNoDescription    "  💬 Placeholder 'No Description'" 0
@var checkbox showRepository      "  📗 Show Repository Icon" 1

@var checkbox hideForked          "  🍴 Hide Forked Text" 0
@var checkbox hideTopics          "  🌍 Hide Topics" 1
@var checkbox hideHelp	          "  🆘 Hide Help Wanted" 1
@var checkbox hideLicense	      "  🪪 Hide License" 1

@var select starsTap              "⭐ Stars Tap" ["Enabled", "Disabled"]
@var checkbox stNoDescription     "  💬 Placeholder 'No Description'" 0
@var checkbox stHideSponsors      "  💵 Hide Sponsors" 1
@var checkbox stHideAuthor        "  🖊️ Hide Author" 1

@var select searchPage          "🔎 Search Page" ["Enabled", "Disabled"]
@var checkbox spHideSponsors      "  💵 Hide Sponsors" 1
@var checkbox spHideTopics        "  🌍 Hide Topics" 1
@var checkbox spHideUpdate        "  💬 Hide Update Text" 1
@var checkbox spfullDescription   "  💬 Full Description" 1
@var checkbox spHideHelp	      "  🆘 Hide Help Wanted" 1

==/UserStyle== */
@-moz-document regexp("https?://github?.com(/.*)?") {
    /* Variables */
    i=!important;
    t=!transparent;

    :root {
        --repository-icon: url("data:image/png;base64,")
    }

    gridTemplate() {
        display: grid;
        grid-template-columns: repeat(2, 1fr);
        gap: 16px;
    }

    description() {
        white-space: nowrap;
        overflow: hidden;
        text-overflow: ellipsis;
    }

    noDescription() {
        content: "No description provided"
        color: var(--fgColor-muted, var(--color-fg-muted)) i;
        font-style: italic;
    }

    itemCard() {
        padding: 16px i;
        background-color: var(--color-canvas-default);
        border-color: var(--color-border-default);
        border-radius: var(--primer-borderRadius-medium, 6px);
        border-style: solid;
        border-width: var(--primer-borderWidth-thin, 1px);
    }

    if (starsTap=="Enabled") {
        #user-starred-repos .mt-5 {
            position: relative;
            max-width: 100% i;

            .col-lg-12 {
                gridTemplate();
                margin-top: 90px;

                .py-4 {
                    itemCard();
                    if (stNoDescription) {
                        > div:nth-child(3):not(:has(p[itemprop="description"]))::before {
                            noDescription()
                        }
                    }
                }

                p[itemprop="description"] {
                    width: 100%;
                }

                > .position-relative {
                    top: 0;
                    position: absolute i;
                    width: 100% i;
                }

                if starNewDesign {
                    form > button > span {
                        display: none i if hideStarText;
                    }

                    .mr-2 {
                        margin-right: 0 i;
                    }

                    .BtnGroup-parent:first-child .BtnGroup-item {
                        border-right-width: 1px;
                        border-top-right-radius: 6px;
                        border-bottom-right-radius: 6px;
                    }

                    details[id^="details-user-list"] {
                        display: none i if dropDownMenu;
                    }
                }

                a[href^="/sponsors/"] {
                    display: none i if stHideSponsors;
                }

                span.text-normal {
                    display: none i if stHideAuthor;
                }
            }
        }
    }

    if (searchPage=="Enabled") {
        /* Search  */
        ul.repo-list {
            gridTemplate();
            margin-top: 16px;

            * {
                min-width: 0 i;
            }

            > li.py-4 {
                itemCard();

                p.mb-1 {
                    if (not spfullDescription) {
                        description()
                    }
                }

                div.mr-3:has( > relative-time) {
                    display: none if spHideUpdate;
                }

                div.d-flex > div.d-flex.flex-items-center.flex-justify-end.flex-shrink-0.flex-auto {
                    display: none i if spHideSponsors;
                }

                a[href^="/topics/"] {
                    display: none i if spHideTopics;
                }

                a[href*="issue"] {
                    display: none if spHideHelp;
                }
            }
        }
    }

    if (resTap=="Enabled") {

        /* Repositories tap */
        #user-repositories-list > ul {
            gridTemplate();
            margin-top: 16px;

            > li.py-4 {
                itemCard();

                min-width: 0;
                padding: 16px i;
                position: relative;

                > .d-inline-block {

                    /* Repository's name */
                    div.d-inline-block.mb-1 {

                        > h3 {
                            font-size: 14px;
                            if showRepository {
                                &::before {
                                    display: inline-block i;
                                    position: relative;
                                    top: 3px;
                                    margin-right: 4px;
                                    width: 16px;
                                    height: 16px;
                                    content: var(--repository-icon);
                                }
                            }
                        }

                        > span {
                            display: none if hideForked;
                        }
                    }

                    /* Description */
                    p.col-9 {
                        margin-bottom: 0 i;

                        width: 100%;

                        if (not fullDescription) {
                            description()
                        }
                    }

                    if (resNoDescription) {
                        > div:nth-child(2):not(:has(p[itemprop="description"]))::before {
                            noDescription()
                        }
                    }

                    /* Hide Topics */
                    > .topics-row-container {
                        display: none i if hideTopics;
                    }

                    /* Bottom descriptions  */
                    div.f6.color-fg-muted.mt-2 {
                        > span:not(.ml-0) {
                            display: none i if hideLicense;
                        }

                        a[href*="issue"] {
                            display: none if hideHelp;
                        }
                    }
                }

                > .col-2 {
                    display: contents i;

                    .starring-container .unstarred, .starring-container.on .starred {
                        margin-left: 0;
                    }

                    .starring-container {
                        position: absolute;
                        right: 16px;

                        if (starNewDesign=="Enabled") {

                            if dropDownMenu {
                                .BtnGroup-parent .BtnGroup-item {
                                    border-right-width: 1px;
                                    border-top-right-radius: 6px;
                                    border-bottom-right-radius: 6px;
                                }

                                details {
                                    display: none i;
                                }
                            }

                            if hideStarText {
                                form > button > span {
                                    display: none i;
                                }

                                .btn-sm .octicon,
                                .starred .starred-button-icon {
                                    margin-right: 0 i;
                                }
                            }
                        }
                    }
                }

                .col-lg-9 {
                    width: 100%;
                }

                .col-9,
                .f6 {
                    font-size: 12px i;
                }

                /* Remove graph */
                div.text-right.hide-lg.hide-md.hide-sm.hide-xs.flex-self-end,
                div.text-right.hide-lg.hide-md.hide-sm.hide-xs.flex-self-end.mt-2 {
                    display: none i;
                }
            }
        }
    }
}

/* ==UserStyle==
@name         GitHub Custom Contributions
@namespace    userstyles.world/user/vednoc
@description  Set custom colors for GitHub contributions.
@author       vednoc <vednoc@pm.me> (https://github.com/vednoc)
@version      0.1.0
@license      MIT
@preprocessor stylus
@var select theme "Color theme" [
    "0:Default theme",
    "1:Halloween",
    "2:Winter Solstice",
    "3:Custom theme*",
]
@var color level1 "Level 1 color" #440e3b
@var color level2 "Level 2 color" #860075
@var color level3 "Level 3 color" #bc30d0
@var color level4 "Level 4 color" #d78ce6
==/UserStyle== */

bg() { background-color: arguments }
t = transparent
i = !important

@-moz-document domain('github.com') {
    if theme > 0 {
        if theme == 1 {
            l1 = #631c03
            l2 = #bd561d
            l3 = #fa7a18
            l4 = #fddf68
        } else if theme == 2 {
            l1 = #0A3069
            l2 = #0969DA
            l3 = #54AEFF
            l4 = #B6E3FF
        } else {
            l1 = level1
            l2 = level2
            l3 = level3
            l4 = level4
        }

        .ContributionCalendar-day {
            &[data-level='1'] { bg: l1 i; fill: l1 i }
            &[data-level='2'] { bg: l2 i; fill: l2 i }
            &[data-level='3'] { bg: l3 i; fill: l3 i }
            &[data-level='4'] { bg: l4 i; fill: l4 i }
        }

        .activity-overview {
            &-box [fill='#40c463'],
            &-box [fill='#ffc501'] {
                fill:   l2 i
                stroke: l2 i
            }

            &-axis,
            &-point {
                fill:   l4 i
                stroke: l3 i
            }
        }

        .Progress-item {
            &[style*="#216e39"] { bg: l1 i }
            &[style*="#30a14e"] { bg: l2 i }
            &[style*="#40c463"] { bg: l3 i }
            &[style*="#9be9a8"] { bg: l4 i }
        }
    }
}

/* ==UserStyle==
@name         GitHub Code Wrap
@version      1.1.0
@description  Userstyle to wrap long code lines on GitHub
@namespace    StylishThemes
@author       StylishThemes
@homepageURL  https://github.com/StylishThemes/GitHub-code-wrap
@supportURL   https://github.com/StylishThemes/GitHub-code-wrap/issues
@license      CC-BY-SA-4.0
@preprocessor uso
==/UserStyle== */
@-moz-document domain("github.com"), domain("gist.github.com") {
  .blob-code-inner, .markdown-body pre > code, .markdown-body .highlight > pre {
    white-space: pre-wrap !important;
    overflow-wrap: anywhere !important;
  }
  /* GitHub Bug: Enable wrapping of long code lines */
  body:not(.nowrap) .blob-code-inner,
  body:not(.nowrap) .markdown-body pre > code,
  body:not(.nowrap) .markdown-body .highlight > pre {
    white-space: pre-wrap !important;
    overflow-wrap: anywhere !important;
    display: block !important;
    word-break: break-all !important;
  }
  body:not(.nowrap) td.blob-code-inner {
    display: table-cell !important;
  }
}

/* ==UserStyle==
@name           GitHub Actions WideScreen 
@namespace      github.com/openstyles/stylus
@version        1.0.2
@description    GitHub Actions wide screen and properly alligned columns.
@author         akaine
==/UserStyle== */

@-moz-document regexp("https://github.com/.*/actions(\\?.*)?") {
    .container-xl {
        max-width: 100% !important;
    }

    .d-table.col-12 > div:first-child {
        width: 100%;
    }

    .d-table.col-12 div.text-right {
        margin-left: 10px;
    }

    .d-table.col-12 div.d-none .d-md-block {
        width: 130px;
    }

    [title="Start time"] {
        white-space: nowrap;
    }

}

/* ==UserStyle==
@name         github-monday
@author       Karl_255
@namespace    github.com/Karl255
@version      1.0.4
@description  Changes the GitHub contribution graph's first day of week on user profiles to Monday instead of Sunday.
@homepageURL  https://github.com/Karl255/UserCSS-Styles
@supportURL   https://github.com/Karl255/UserCSS-Styles/issues
@license      unlicense
@preprocessor default
==/UserStyle== */

@-moz-document domain("github.com") {
	/* when the activity overview is enabled the grid rects are 10px * 10px (3px spacing) */
	.ContributionCalendar-grid[style*="border-spacing: 3px"] {
		--dist: 13px;
	}

	/* but when it's disabled, they're 11px * 11px (4px spacing) */
	.ContributionCalendar-grid[style*="border-spacing: 4px"] {
		--dist: 15px;
	}

	/* all days up a little */
	.ContributionCalendar-grid tbody tr {
		transform: translateY(calc(var(--dist) * -1));
	}

	/* all sundays all the way down */
	.ContributionCalendar-grid tbody tr:first-child {
		transform: translateY(calc(var(--dist) * 6));
	}

	/* hide first sunday (otherwise it'll be outside the box) */
	.ContributionCalendar-grid tbody tr:first-child .ContributionCalendar-label + * {
		display: none;
	}

	/* show sunday text */
	.ContributionCalendar-grid tbody tr:first-child .ContributionCalendar-label span:last-child  {
		clip-path: unset !important;
	}
}

